  "steps": [
    {
      "task": "detect_and_extract_spatial_temporal",
      "player": "spatial_temporal_specialist",
      "rationale": "Detect temporal and spatial columns in the CSV, then compute the bounding box and date range required by the iNaturalist Croissant standard.",
      "inputs": {},
      "outputs": ["spatial_temporal_data"]
    },
    {
      "task": "generate_iNaturalist_metadata",
      "player": "croissant_inaturalist_metadata_generator",
      "rationale": "Create the final metadata JSON containing spatialCoverage and temporalCoverage using the extracted spatial‑temporal artifact and the standard definition.",
      "inputs": {
        "metadata_standard": "metadata_standard",
        "spatial_temporal": "spatial_temporal_data"
      },
      "outputs": ["metadata_output"]
    }
  ]
}

